import{_ as i,o as n,c as t,a3 as r}from"./chunks/framework.BwzYn71E.js";const p=JSON.parse('{"title":"Xiragen\\\\Acridgen in Series","description":"","frontmatter":{"translationSource":{"title":"息壤气\\\\酸气串行","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=QSB4bZ80E13jewhwgGVnJ4","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/xiragen-acridgen-in-series"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/xiragen-acridgen-in-series"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/xiragen-acridgen-in-series"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/xiragen-acridgen-in-series"}]]},"headers":[],"relativePath":"xiragen-acridgen-in-series.md","filePath":"logistics/src/page-QSB4bZ80E13jewhwgGVnJ4.md"}'),a={name:"xiragen-acridgen-in-series.md"};function s(o,e,d,c,l,g){return n(),t("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="xiragen-acridgen-in-series" tabindex="-1">Xiragen\\Acridgen in Series <a class="header-anchor" href="#xiragen-acridgen-in-series" aria-label="Permalink to &quot;Xiragen\\\\Acridgen in Series&quot;">​</a></h1><blockquote><p>Source page ID: <code>QSB4bZ80E13jewhwgGVnJ4</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=QSB4bZ80E13jewhwgGVnJ4" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>The structure was provided by 断懒, as shown in the figure.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fefee1e7bfaba543.jpeg" alt="XiragenAcridgen in Series"></p><p>Given that Acridgen is consumed extremely slowly and Xiragen extremely fast, producing Acridgen involves a period of blocking, whereas producing Xiragen can be treated as immediate output.</p><p>Only one or two drops of acid liquid almost always enter and are converted into Acridgen, after which the input switches to Liquid Xiranite.</p><p>While the Acridgen produced has not yet been output, the buffer of 50 inside the Fluid-Gas Transmuting Unit is enough to buffer a full 2 min of Liquid Xiranite input.</p><p>During this period, once the Acridgen is consumed, the Liquid Xiranite begins converting into Xiragen at 30 units/min and that Xiragen is output: 30 units/min consumed &gt; 24 units/min input, so the Liquid Xiranite is eventually used up entirely.</p><p>The acid liquid that has been blocked at the inlet then enters the transmuting unit, beginning a new cycle.</p></div>',1)])])}const u=i(a,[["render",s]]);export{p as __pageData,u as default};
